class Solution {
  public int longestSubsequence(int[] nums) {
    int V = 301;
    int[][] exact = new int[V][V + 1], suf = new int[V][V + 1];
    boolean[] seen = new boolean[V];
    int ans = 1;
    int[] cand = new int[V];
    for (int x : nums) {
      for (int y = 1; y < V; y++) {
        cand[y] = 0;
        if (!seen[y]) continue;
        int d = Math.abs(x - y);
        cand[y] = Math.max(suf[y][d], 1) + 1;
      }
      for (int y = 1; y < V; y++) {
        if (cand[y] == 0) continue;
        int d = Math.abs(x - y);
        if (cand[y] > exact[x][d]) exact[x][d] = cand[y];
        if (cand[y] > ans) ans = cand[y];
      }
      seen[x] = true;
      for (int d = V - 1; d >= 0; d--) suf[x][d] = Math.max(suf[x][d + 1], exact[x][d]);
    }
    return ans;
  }
}
